create table content_ideas (id uuid primary key, title text not null, hook text not null, category varchar(40) not null, format varchar(40) not null, estimated_duration_sec int not null check (estimated_duration_sec > 0), status varchar(24) not null, score int check (score between 0 and 100), language varchar(16) not null, niche text not null, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index idx_ideas_status_created on content_ideas(status, created_at desc);
create table contents (id uuid primary key, title text not null, topic text not null, status varchar(32) not null, current_stage varchar(32) not null, progress_percent int not null default 0 check (progress_percent between 0 and 100), idea_id uuid references content_ideas(id) on delete set null, language varchar(16) not null, niche text not null, tags text[] not null default '{}', scheduled_publication_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index idx_contents_status_stage on contents(status,current_stage);
create table stage_progress (content_id uuid not null references contents(id) on delete cascade, stage varchar(32) not null, status varchar(24) not null, started_at timestamptz, completed_at timestamptz, error text, retry_count int not null default 0, primary key(content_id,stage));
create table storyboards (id uuid primary key, content_id uuid not null unique references contents(id) on delete cascade, title text not null, total_duration_sec int not null default 0, version int not null default 1, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table scenes (id uuid primary key, storyboard_id uuid not null references storyboards(id) on delete cascade, scene_number int not null, duration_sec int not null check(duration_sec > 0), narration text not null, visual_type varchar(24) not null, prompt text not null, asset_status varchar(32) not null default 'NOT_STARTED', asset_id uuid, notes text, unique(storyboard_id,scene_number));
create table assets (id uuid primary key, filename text not null, asset_type varchar(24) not null, content_id uuid references contents(id) on delete set null, scene_id uuid references scenes(id) on delete set null, duration_sec numeric, file_size_bytes bigint not null check(file_size_bytes > 0), mime_type varchar(120) not null, storage_path text not null, metadata jsonb not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
alter table scenes add constraint fk_scene_asset foreign key(asset_id) references assets(id) on delete set null;
create index idx_assets_content on assets(content_id);
create table workflow_instances (id uuid primary key, content_id uuid not null references contents(id) on delete cascade, status varchar(24) not null, current_node text, started_at timestamptz, completed_at timestamptz, retry_count int not null default 0, error text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create unique index idx_active_workflow on workflow_instances(content_id) where status in ('CREATED','RUNNING','WAITING');
create table workflow_node_executions (id uuid primary key, workflow_instance_id uuid not null references workflow_instances(id) on delete cascade, node_name text not null, node_type text not null, status varchar(24) not null, started_at timestamptz, completed_at timestamptz, retry_count int not null default 0, error text, input jsonb, output jsonb);
create index idx_nodes_workflow on workflow_node_executions(workflow_instance_id,started_at);
create table render_jobs (id uuid primary key, content_id uuid not null references contents(id) on delete cascade, status varchar(24) not null, progress_percent int not null default 0, started_at timestamptz, completed_at timestamptz, worker text, retry_count int not null default 0, max_retries int not null default 3, error text, output_asset_id uuid references assets(id), logs jsonb not null default '[]', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create unique index idx_active_render on render_jobs(content_id) where status in ('QUEUED','RENDERING','RETRYING');
create table publication_jobs (id uuid primary key, content_id uuid not null references contents(id) on delete cascade, platform varchar(32) not null, status varchar(24) not null, scheduled_at timestamptz, published_at timestamptz, caption text not null, title text not null, hashtags text[] not null default '{}', attempts int not null default 0, max_attempts int not null default 3, error text, platform_post_id text, approved_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index idx_publication_due on publication_jobs(status,scheduled_at);
create unique index idx_platform_post on publication_jobs(platform,platform_post_id) where platform_post_id is not null;
create table activity_events (id uuid primary key, timestamp timestamptz not null default now(), type varchar(48) not null, entity_id uuid, entity_type varchar(40), message text not null, severity varchar(16) not null, metadata jsonb not null default '{}');
create index idx_events_entity on activity_events(entity_id,timestamp desc);
create table system_settings (key varchar(100) primary key, value jsonb not null, updated_at timestamptz not null default now());
create table ai_generation_jobs (id uuid primary key, content_id uuid references contents(id), type varchar(32) not null, status varchar(24) not null, provider varchar(32), model text, prompt text not null, response text, input_tokens int, output_tokens int, error text, duration_ms bigint, retry_count int not null default 0, idempotency_key text unique, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table social_connections (id uuid primary key, platform varchar(32) not null unique, status varchar(24) not null, encrypted_refresh_token bytea, scopes text[] not null default '{}', expires_at timestamptz, revoked_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table provider_usage (id uuid primary key, provider varchar(32) not null, model text, generation_job_id uuid references ai_generation_jobs(id), input_tokens int not null default 0, output_tokens int not null default 0, cost_usd numeric(12,6) not null default 0, created_at timestamptz not null default now());
